begin;
create table if not exists public.mme_procurement_vendors(vendor_id uuid primary key default gen_random_uuid(),vendor_code text not null unique,vendor_name text not null,tax_reference_last4 text,default_currency char(3) not null default 'USD',payment_terms text,status text not null default 'active' check(status in ('active','on_hold','inactive')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_employee_expense_reports(expense_report_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null,report_number text not null unique,period_start date not null,period_end date not null,currency char(3) not null default 'USD',total_amount numeric(16,2) not null default 0 check(total_amount>=0),status text not null default 'draft' check(status in ('draft','submitted','approved','rejected','paid')),submitted_at timestamptz,approved_by_auth_user_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),check(period_end>=period_start),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>employee_auth_user_id));
create table if not exists public.mme_employee_expense_items(expense_item_id uuid primary key default gen_random_uuid(),expense_report_id uuid not null references public.mme_employee_expense_reports(expense_report_id),expense_date date not null,category text not null check(category in ('travel','meals','mileage','supplies','equipment','software','other')),description text not null,amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',receipt_reference text,receipt_storage_path text,gl_account_code text,created_at timestamptz not null default now());
create table if not exists public.mme_expense_approvals(approval_id uuid primary key default gen_random_uuid(),expense_report_id uuid not null references public.mme_employee_expense_reports(expense_report_id),approval_step integer not null default 1,approver_auth_user_id uuid,decision text not null default 'pending' check(decision in ('pending','approved','rejected')),note text,decided_at timestamptz,unique(expense_report_id,approval_step));
create table if not exists public.mme_purchase_requisitions(requisition_id uuid primary key default gen_random_uuid(),requisition_number text not null unique,requester_auth_user_id uuid not null,entity_id uuid references public.mme_financial_reporting_entities(entity_id),department_code text,purpose text not null,requested_date date not null,required_by date,currency char(3) not null default 'USD',estimated_total numeric(16,2) not null check(estimated_total>=0),status text not null default 'draft' check(status in ('draft','submitted','approved','rejected','converted','cancelled')),approved_by_auth_user_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),check(required_by is null or required_by>=requested_date),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>requester_auth_user_id));
create table if not exists public.mme_purchase_orders(purchase_order_id uuid primary key default gen_random_uuid(),po_number text not null unique,requisition_id uuid references public.mme_purchase_requisitions(requisition_id),vendor_id uuid not null references public.mme_procurement_vendors(vendor_id),entity_id uuid references public.mme_financial_reporting_entities(entity_id),order_date date not null,currency char(3) not null default 'USD',subtotal numeric(16,2) not null check(subtotal>=0),tax_amount numeric(16,2) not null default 0 check(tax_amount>=0),total_amount numeric(16,2) generated always as(subtotal+tax_amount) stored,status text not null default 'draft' check(status in ('draft','pending_approval','approved','sent','partially_received','received','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>created_by_auth_user_id));
create table if not exists public.mme_purchase_order_lines(po_line_id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.mme_purchase_orders(purchase_order_id),description text not null,sku text,quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(16,4) not null check(unit_cost>=0),line_total numeric(16,2) generated always as(round(quantity*unit_cost,2)) stored);
create table if not exists public.mme_corporate_card_transactions(card_transaction_id uuid primary key default gen_random_uuid(),provider_reference text not null unique,employee_auth_user_id uuid,merchant text not null,transaction_date date not null,amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',status text not null default 'imported' check(status in ('imported','matched','review','disputed','reconciled')),expense_item_id uuid references public.mme_employee_expense_items(expense_item_id),created_at timestamptz not null default now());
create table if not exists public.mme_recurring_expenses(recurring_expense_id uuid primary key default gen_random_uuid(),vendor_id uuid references public.mme_procurement_vendors(vendor_id),description text not null,category text not null,amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',cadence text not null check(cadence in ('weekly','monthly','quarterly','annual')),next_due_date date not null,gl_account_code text,status text not null default 'active' check(status in ('active','paused','cancelled')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_expense_reimbursements(reimbursement_id uuid primary key default gen_random_uuid(),expense_report_id uuid not null references public.mme_employee_expense_reports(expense_report_id),amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',status text not null default 'pending' check(status in ('pending','approved','paid','rejected')),payment_reference text,paid_at timestamptz,created_at timestamptz not null default now());
create index if not exists mme_expense_report_employee_idx on public.mme_employee_expense_reports(employee_auth_user_id,status);
create index if not exists mme_requisition_status_date_idx on public.mme_purchase_requisitions(status,requested_date);
create index if not exists mme_purchase_order_vendor_date_idx on public.mme_purchase_orders(vendor_id,order_date);
create index if not exists mme_card_tx_status_date_idx on public.mme_corporate_card_transactions(status,transaction_date);
create or replace function public.mme_submit_expense_report(p_id uuid,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$declare e public.mme_employee_expense_reports%rowtype;begin select * into e from public.mme_employee_expense_reports where expense_report_id=p_id for update;if not found or e.status<>'draft' then raise exception 'expense_report_not_draft';end if;if e.employee_auth_user_id<>p_actor then raise exception 'expense_report_owner_mismatch';end if;if not exists(select 1 from public.mme_employee_expense_items where expense_report_id=p_id) then raise exception 'expense_report_empty';end if;update public.mme_employee_expense_reports set total_amount=(select sum(amount) from public.mme_employee_expense_items where expense_report_id=p_id),status='submitted',submitted_at=now() where expense_report_id=p_id;insert into public.mme_expense_approvals(expense_report_id) values(p_id) on conflict do nothing;return p_id;end$$;
create or replace function public.mme_decide_expense_report(p_id uuid,p_decision text,p_note text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$declare e public.mme_employee_expense_reports%rowtype;begin if p_decision not in('approved','rejected') then raise exception 'invalid_expense_decision';end if;select * into e from public.mme_employee_expense_reports where expense_report_id=p_id for update;if not found or e.status<>'submitted' then raise exception 'expense_report_not_submitted';end if;if e.employee_auth_user_id=p_actor then raise exception 'expense_self_approval_prohibited';end if;update public.mme_expense_approvals set approver_auth_user_id=p_actor,decision=p_decision,note=left(coalesce(p_note,''),1000),decided_at=now() where expense_report_id=p_id and approval_step=1 and decision='pending';if not found then raise exception 'expense_approval_step_missing';end if;update public.mme_employee_expense_reports set status=p_decision,approved_by_auth_user_id=case when p_decision='approved' then p_actor end,approved_at=case when p_decision='approved' then now() end where expense_report_id=p_id;return p_id;end$$;
do $$declare t text;begin foreach t in array array['mme_procurement_vendors','mme_employee_expense_reports','mme_employee_expense_items','mme_expense_approvals','mme_purchase_requisitions','mme_purchase_orders','mme_purchase_order_lines','mme_corporate_card_transactions','mme_recurring_expenses','mme_expense_reimbursements'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.mme_submit_expense_report(uuid,uuid),public.mme_decide_expense_report(uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_submit_expense_report(uuid,uuid),public.mme_decide_expense_report(uuid,text,text,uuid) to service_role;
commit;